do $$ begin if not exists(select 1 from public.catalogue_sources where id='2026-TNWWE-BASE-118-SOURCE' and notes='US sale window 2026-11-03 to 2026-11-06. Official Topps product number 118; physical back not independently inspected. Official archive print run 336, verified 2026-11-11. Conditional Chrome/Opal editions excluded.') then raise exception 'Missing final note'; end if; end $$;
do $$ begin if not exists(select 1 from public.catalogue_sources where id='2026-TNWWE-POSTER-CJ26-SOURCE' and notes='Official Topps product title identifies CJ26. Topps US and UK now show on-sale 2026-11-06, replacing 2026-10-30. Earlier pages listed close 2026-11-09; current sold-out pages omit the close date. Official archive print run 668. US shipping 7-10 business days after close. Rainbow quantity and physical card-back code unverified. Conditional Chrome/Opal editions excluded.') then raise exception 'Missing final note'; end if; end $$;
do $$ begin if not exists(select 1 from public.catalogue_sources where id='2026-TNWWE-POSTER-CJ26-SOURCE-UK' and notes='UK on-sale date revised to 2026-11-06 from 2026-10-30. Earlier listing closed 2026-11-09; current sold-out page omits the close date. Official archive print run 668. Estimated shipping 15-20 business days after close. Announcement date and exact dispatch date unconfirmed.') then raise exception 'Missing final note'; end if; end $$;
select 'Six print runs and CJ26 date verified' as result, (select count(*) from public.collection_items) as preserved_collections;
commit;
